<template>
  <q-page class="q-pa-lg">
    <div class="row items-center justify-between q-mb-md">
      <div>
        <div class="text-h5 text-weight-bold">
          <q-icon name="manage_accounts" color="primary" class="q-mr-sm" />
          Quản lý Tài khoản & Phân quyền Camera (Channel RBAC)
        </div>
        <div class="text-caption text-grey-6">
          Phân quyền xem 32 kênh camera chi tiết cho từng tài khoản và phòng ban
        </div>
      </div>
      <div class="row q-gutter-sm">
        <q-btn outline color="primary" icon="refresh" label="Tải lại" @click="fetchUsers" />
        <q-btn unelevated color="primary" icon="person_add" label="Thêm Tài Khoản" @click="openCreateDialog" />
      </div>
    </div>

    <!-- Users Table -->
    <q-card>
      <q-table
        :rows="systemUsers"
        :columns="userColumns"
        row-key="username"
        flat
        :pagination="{ rowsPerPage: 10 }"
        no-data-label="Chưa có người dùng nào"
      >
        <template #body-cell-username="props">
          <q-td :props="props">
            <div class="row items-center no-wrap">
              <q-avatar size="28px" class="q-mr-sm" v-if="props.row.avatar_url">
                <img :src="props.row.avatar_url" referrerpolicy="no-referrer">
              </q-avatar>
              <q-avatar size="28px" class="q-mr-sm" :color="props.row.auth_provider === 'google' ? 'red-8' : 'blue-grey-6'" text-color="white" :icon="props.row.auth_provider === 'google' ? 'mail' : 'person'" v-else />
              <div>
                <div class="text-weight-bold">{{ props.row.username }}</div>
                <div class="row items-center q-gutter-xs">
                  <q-badge v-if="props.row.auth_provider === 'google'" color="red-8" text-color="white" size="xs">
                    Google SSO
                  </q-badge>
                  <q-badge v-else color="grey-6" text-color="white" size="xs">
                    Nội bộ
                  </q-badge>
                </div>
              </div>
            </div>
          </q-td>
        </template>

        <template #body-cell-role="props">
          <q-td :props="props">
            <q-badge :color="props.row.role === 'admin' ? 'negative' : (props.row.role === 'operator' ? 'primary' : 'teal')" :label="props.row.role.toUpperCase()" />
          </q-td>
        </template>

        <template #body-cell-channels="props">
          <q-td :props="props">
            <div v-if="props.row.role === 'admin' || props.row.allowed_channels.includes('*')">
              <q-chip color="cyan-9" text-color="white" dense icon="star">Toàn quyền (Tất cả 32 Kênh)</q-chip>
            </div>
            <div v-else-if="props.row.allowed_channels.length === 0">
              <q-chip color="red-10" text-color="red-2" dense icon="block">Chưa cấp kênh nào</q-chip>
            </div>
            <div v-else class="row items-center q-gutter-xs">
              <q-chip color="blue-grey-9" text-color="cyan-3" dense icon="videocam">
                {{ props.row.allowed_channels.length }} Kênh Camera
              </q-chip>
              <span class="text-caption text-grey-6 gt-sm">
                (Kênh {{ props.row.allowed_channels.slice(0, 6).join(', ') }}{{ props.row.allowed_channels.length > 6 ? '...' : '' }})
              </span>
            </div>
          </q-td>
        </template>

        <template #body-cell-actions="props">
          <q-td :props="props" class="q-gutter-xs">
            <q-btn flat dense round color="primary" icon="edit" @click="openEditDialog(props.row)">
              <q-tooltip>Chỉnh sửa & Phân quyền</q-tooltip>
            </q-btn>
            <q-btn flat dense round color="negative" icon="delete" v-if="props.row.username !== 'aicamera'" @click="confirmDelete(props.row)">
              <q-tooltip>Xóa tài khoản</q-tooltip>
            </q-btn>
            <q-icon name="lock" color="grey-5" size="20px" v-else>
              <q-tooltip>Tài khoản Quản trị viên chính được bảo vệ</q-tooltip>
            </q-icon>
          </q-td>
        </template>
      </q-table>
    </q-card>

    <!-- Dialog: Add / Edit User with 32 Camera Matrix -->
    <q-dialog v-model="dialog.show" persistent maximized transition-show="slide-up" transition-hide="slide-down">
      <q-card class="column">
        <q-card-section class="row items-center justify-between bg-primary text-white">
          <div class="row items-center">
            <q-avatar size="36px" color="white" text-color="primary" class="q-mr-sm">
              <q-icon :name="dialog.isEdit ? 'manage_accounts' : 'person_add'" />
            </q-avatar>
            <div>
              <div class="text-h6 text-weight-bold">
                {{ dialog.isEdit ? 'Chỉnh Sửa Tài Khoản: ' + dialog.form.username : 'Tạo Tài Khoản Mới & Phân Quyền Camera' }}
              </div>
              <div class="text-caption text-grey-2">
                Thiết lập mật khẩu và chọn phạm vi camera được phép theo dõi
              </div>
            </div>
          </div>
          <q-btn flat round dense icon="close" v-close-popup />
        </q-card-section>

        <q-card-section class="col q-pa-lg scroll">
          <div class="row q-col-gutter-lg">
            <!-- Account Info -->
            <div class="col-12 col-md-4">
              <q-card bordered class="q-pa-md">
                <div class="text-subtitle1 text-weight-bold text-primary q-mb-md">Thông Tin Đăng Nhập</div>
                <div class="q-gutter-md">
                  <q-input v-model="dialog.form.username" label="Tên đăng nhập *" outlined dense :disable="dialog.isEdit" :rules="[v => !!v || 'Bắt buộc']">
                    <template #prepend><q-icon name="account_circle" color="primary" /></template>
                  </q-input>

                  <q-input v-model="dialog.form.full_name" label="Họ tên / Đơn vị" placeholder="VD: Nguyễn Văn A - Ban Giám Hiệu" outlined dense>
                    <template #prepend><q-icon name="badge" color="primary" /></template>
                  </q-input>

                  <q-input v-model="dialog.form.password" :type="showPass ? 'text' : 'password'" :label="dialog.isEdit ? 'Mật khẩu mới (Bỏ trống nếu giữ nguyên)' : 'Mật khẩu *'" outlined dense :rules="dialog.isEdit ? [] : [v => !!v || 'Bắt buộc']">
                    <template #prepend><q-icon name="lock" color="primary" /></template>
                    <template #append>
                      <q-icon :name="showPass ? 'visibility_off' : 'visibility'" class="cursor-pointer" @click="showPass = !showPass" />
                    </template>
                  </q-input>

                  <q-select v-model="dialog.form.role" :options="roleOptions" emit-value map-options label="Vai trò tài khoản *" outlined dense>
                    <template #prepend><q-icon name="admin_panel_settings" color="primary" /></template>
                  </q-select>

                  <div v-if="dialog.form.role === 'admin'" class="q-pa-sm bg-blue-1 text-primary rounded-borders text-caption">
                    <q-icon name="info" class="q-mr-xs" />
                    Quản trị viên (Admin) tự động có quyền xem tất cả 32 camera và quản trị toàn bộ hệ thống.
                  </div>
                </div>
              </q-card>
            </div>

            <!-- 32 Camera Checkbox Matrix -->
            <div class="col-12 col-md-8">
              <q-card bordered class="q-pa-md">
                <div class="row items-center justify-between q-mb-sm">
                  <div>
                    <div class="text-subtitle1 text-weight-bold text-primary">
                      <q-icon name="grid_view" class="q-mr-xs" />
                      Ma Trận Phân Quyền Camera (Kênh 1 - 32)
                    </div>
                    <div class="text-caption text-grey-7">
                      Đã chọn: <b class="text-primary">{{ dialog.form.role === 'admin' ? 32 : dialog.form.allowed_channels.length }} / 32</b> Camera
                    </div>
                  </div>

                  <!-- Quick Presets -->
                  <div class="row q-gutter-xs" v-if="dialog.form.role !== 'admin'">
                    <q-btn outline dense size="sm" color="primary" label="Tất cả 32 Kênh" icon="select_all" @click="applyPreset('all')" />
                    <q-btn outline dense size="sm" color="grey-7" label="Bỏ chọn hết" icon="clear" @click="applyPreset('none')" />
                    <q-btn outline dense size="sm" color="amber-9" label="Sảnh (18-20)" icon="store" @click="applyPreset('lobby')" />
                    <q-btn outline dense size="sm" color="green-8" label="Phòng ban (1-16)" icon="apartment" @click="applyPreset('office')" />
                    <q-btn outline dense size="sm" color="purple-8" label="Hành lang (21-24)" icon="meeting_room" @click="applyPreset('corridor')" />
                  </div>
                </div>
                <q-separator class="q-mb-md" />

                <!-- Grid -->
                <div class="camera-matrix-grid">
                  <div
                    v-for="cam in allCameras"
                    :key="cam.channel"
                    class="camera-matrix-item"
                    :class="{ 'selected': dialog.form.role === 'admin' || dialog.form.allowed_channels.includes(cam.channel) }"
                    @click="toggleCamera(cam.channel)"
                  >
                    <div class="row items-center justify-between no-wrap">
                      <div class="row items-center no-wrap" style="overflow: hidden;">
                        <q-checkbox
                          :model-value="dialog.form.role === 'admin' || dialog.form.allowed_channels.includes(cam.channel)"
                          :disable="dialog.form.role === 'admin'"
                          color="primary"
                          dense
                          class="q-mr-xs"
                          @update:model-value="toggleCamera(cam.channel)"
                        />
                        <div style="overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                          <div class="text-caption text-weight-bold">{{ cam.name }}</div>
                          <div class="text-grey-6" style="font-size: 0.72rem;">{{ cam.category }}</div>
                        </div>
                      </div>
                      <q-badge v-if="cam.is_active" color="positive" label="ON" size="xs" />
                    </div>
                  </div>
                </div>
              </q-card>
            </div>
          </div>
        </q-card-section>

        <q-separator />
        <q-card-actions align="right" class="q-pa-md">
          <q-btn flat label="Hủy Bỏ" color="grey-7" v-close-popup />
          <q-btn unelevated label="Lưu Tài Khoản & Phân Quyền" color="primary" icon="check" @click="submitDialog" :loading="saving" />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </q-page>
</template>

<script>
import { defineComponent, ref, reactive, onMounted } from 'vue'
import { useQuasar } from 'quasar'

export default defineComponent({
  name: 'UserRbac',
  setup () {
    const $q = useQuasar()
    const systemUsers = ref([])
    const allCameras = ref([])
    const cameraPresets = ref({})
    const saving = ref(false)
    const showPass = ref(false)

    const userColumns = [
      { name: 'username', label: 'Tài khoản', field: 'username', sortable: true, align: 'left' },
      { name: 'full_name', label: 'Họ và tên / Phòng ban', field: 'full_name', sortable: true, align: 'left' },
      { name: 'role', label: 'Vai trò', field: 'role', sortable: true, align: 'center' },
      { name: 'channels', label: 'Quyền Camera (RBAC)', field: 'allowed_channels', align: 'left' },
      { name: 'created_at', label: 'Thời gian tạo', field: 'created_at', sortable: true, align: 'left' },
      { name: 'actions', label: 'Thao tác', align: 'center' }
    ]

    const roleOptions = [
      { label: 'Quản trị viên (Admin) - Toàn quyền', value: 'admin' },
      { label: 'Người trực / Vận hành (Operator)', value: 'operator' },
      { label: 'Người xem (Viewer) - Chỉ xem', value: 'viewer' }
    ]

    const dialog = reactive({
      show: false,
      isEdit: false,
      form: {
        username: '',
        full_name: '',
        password: '',
        role: 'viewer',
        allowed_channels: [1, 2, 3, 4]
      }
    })

    const fetchUsers = async () => {
      try {
        const res = await fetch('/api/admin/users')
        if (res.ok) systemUsers.value = await res.json()
      } catch (err) {
        $q.notify({ type: 'negative', message: 'Lỗi tải người dùng' })
      }
    }

    const fetchCameras = async () => {
      try {
        const res = await fetch('/api/admin/cameras/all')
        if (res.ok) {
          const data = await res.json()
          allCameras.value = data.cameras || []
          cameraPresets.value = data.presets || {}
        }
      } catch (err) {
        console.error(err)
      }
    }

    const openCreateDialog = () => {
      dialog.isEdit = false
      dialog.form = {
        username: '',
        full_name: '',
        password: '',
        role: 'viewer',
        allowed_channels: [1, 2, 3, 4]
      }
      showPass.value = false
      dialog.show = true
    }

    const openEditDialog = (row) => {
      dialog.isEdit = true
      dialog.form = {
        username: row.username,
        full_name: row.full_name || '',
        password: '',
        role: row.role || 'viewer',
        allowed_channels: Array.isArray(row.allowed_channels) ? [...row.allowed_channels] : []
      }
      showPass.value = false
      dialog.show = true
    }

    const toggleCamera = (ch) => {
      if (dialog.form.role === 'admin') return
      const idx = dialog.form.allowed_channels.indexOf(ch)
      if (idx > -1) {
        dialog.form.allowed_channels.splice(idx, 1)
      } else {
        dialog.form.allowed_channels.push(ch)
        dialog.form.allowed_channels.sort((a, b) => a - b)
      }
    }

    const applyPreset = (type) => {
      if (dialog.form.role === 'admin') return
      if (type === 'all') {
        dialog.form.allowed_channels = Array.from({ length: 32 }, (_, i) => i + 1)
      } else if (type === 'none') {
        dialog.form.allowed_channels = []
      } else if (cameraPresets.value[type]) {
        dialog.form.allowed_channels = [...cameraPresets.value[type]]
      }
    }

    const submitDialog = async () => {
      if (!dialog.form.username.trim()) {
        $q.notify({ type: 'warning', message: 'Vui lòng nhập tên tài khoản' })
        return
      }
      if (!dialog.isEdit && !dialog.form.password) {
        $q.notify({ type: 'warning', message: 'Vui lòng nhập mật khẩu' })
        return
      }

      saving.value = true
      try {
        let url = '/api/admin/users'
        let method = 'POST'
        let payload = { ...dialog.form }

        if (dialog.isEdit) {
          url = `/api/admin/users/${encodeURIComponent(dialog.form.username)}`
          method = 'PUT'
          if (!payload.password) delete payload.password
        }

        const res = await fetch(url, {
          method,
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        })
        const data = await res.json()
        if (!res.ok) throw new Error(data.detail || data.message || 'Lỗi lưu tài khoản')

        $q.notify({ type: 'positive', message: data.message || 'Lưu thành công!' })
        dialog.show = false
        await fetchUsers()
      } catch (err) {
        $q.notify({ type: 'negative', message: err.message })
      } finally {
        saving.value = false
      }
    }

    const confirmDelete = (row) => {
      $q.dialog({
        title: 'Xóa tài khoản',
        message: `Bạn có chắc muốn xóa tài khoản "${row.username}" không?`,
        cancel: true,
        persistent: true,
        ok: { label: 'Xóa vĩnh viễn', color: 'negative' }
      }).onOk(async () => {
        try {
          const res = await fetch(`/api/admin/users/${encodeURIComponent(row.username)}`, { method: 'DELETE' })
          const data = await res.json()
          if (!res.ok) throw new Error(data.detail || 'Lỗi xóa')
          $q.notify({ type: 'positive', message: data.message || 'Đã xóa' })
          await fetchUsers()
        } catch (err) {
          $q.notify({ type: 'negative', message: err.message })
        }
      })
    }

    onMounted(() => {
      fetchUsers()
      fetchCameras()
    })

    return {
      systemUsers,
      allCameras,
      userColumns,
      roleOptions,
      dialog,
      saving,
      showPass,
      fetchUsers,
      openCreateDialog,
      openEditDialog,
      toggleCamera,
      applyPreset,
      submitDialog,
      confirmDelete
    }
  }
})
</script>

<style scoped>
.camera-matrix-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 10px;
  max-height: 480px;
  overflow-y: auto;
  padding: 6px;
}

.camera-matrix-item {
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 8px;
  padding: 8px 12px;
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
}

.camera-matrix-item:hover {
  border-color: var(--q-primary);
  background: rgba(0, 210, 211, 0.05);
}

.camera-matrix-item.selected {
  border-color: var(--q-primary);
  background: rgba(0, 210, 211, 0.12);
  font-weight: 600;
}
</style>
